name: Auto Label Issues by Package

on:
  issues:
    types: [opened, edited]

permissions:
  contents: read

jobs:
  label-by-package:
    if: github.repository_owner == 'langchain-ai'
    permissions:
      issues: write
    runs-on: ubuntu-latest

    steps:
      - name: Sync package labels
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const body = context.payload.issue.body || "";

            // Extract text under "## Package" or "### Package" (handles " (Required)" suffix and being last section)
            const match = body.match(/#{2,3} Package[^\n]*\n([\s\S]*?)(?:\n#{2,3} |$)/i);
            if (!match) {
              core.setFailed(
                `Could not find "## Package" section in issue #${context.issue.number} body. ` +
                `The issue template may have changed — update the regex in this workflow.`
              );
              return;
            }

            const packageSection = match[1].trim();

            // Mapping table for package names to labels
            const mapping = {
              "langchain": "langchain",
              "langchain-openai": "openai",
              "langchain-anthropic": "anthropic",
              "langchain-classic": "langchain-classic",
              "langchain-core": "core",
              "langchain-model-profiles": "model-profiles",
              "langchain-tests": "standard-tests",
              "langchain-text-splitters": "text-splitters",
              "langchain-chroma": "chroma",
              "langchain-deepseek": "deepseek",
              "langchain-exa": "exa",
              "langchain-fireworks": "fireworks",
              "langchain-groq": "groq",
              "langchain-huggingface": "huggingface",
              "langchain-mistralai": "mistralai",
              "langchain-nomic": "nomic",
              "langchain-ollama": "ollama",
              "langchain-openrouter": "openrouter",
              "langchain-perplexity": "perplexity",
              "langchain-qdrant": "qdrant",
              "langchain-typesafe": "typesafe",
              "langchain-xai": "xai",
            };

            // All possible package labels we manage
            const allPackageLabels = Object.values(mapping);
            const selectedLabels = [];

            // Check if this is checkbox format (multiple selection)
            const checkboxMatches = packageSection.match(/- \[x\]\s+([^\n\r]+)/gi);
            if (checkboxMatches) {
              // Handle checkbox format
              for (const match of checkboxMatches) {
                const packageName = match.replace(/- \[x\]\s+/i, '').trim();
                const label = mapping[packageName];
                if (label && !selectedLabels.includes(label)) {
                  selectedLabels.push(label);
                }
              }
            } else {
              // Handle dropdown format (single selection)
              const label = mapping[packageSection];
              if (label) {
                selectedLabels.push(label);
              }
            }

            // Get current issue labels
            const issue = await github.rest.issues.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number
            });

            const currentLabels = issue.data.labels.map(label => label.name);
            const currentPackageLabels = currentLabels.filter(label => allPackageLabels.includes(label));

            // Determine labels to add and remove
            const labelsToAdd = selectedLabels.filter(label => !currentPackageLabels.includes(label));
            const labelsToRemove = currentPackageLabels.filter(label => !selectedLabels.includes(label));

            // Add new labels
            if (labelsToAdd.length > 0) {
              await github.rest.issues.addLabels({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.issue.number,
                labels: labelsToAdd
              });
            }

            // Remove old labels
            for (const label of labelsToRemove) {
              await github.rest.issues.removeLabel({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.issue.number,
                name: label
              });
            }

# Block PRs whose head ref is `main` (or `master`) from a fork. This topology
# (`<fork>:master -> langchain-ai/langchain:master`) lets contributors click
# "Update branch" on the PR, producing a `Merge branch 'master' into master`
# commit on the source side that — under admin merge override — can land
# directly on `master` as a 2-parent merge commit, bypassing the repo's
# squash-only policy and polluting the changelog.
#
# `pull_request_target` is required so the job receives a token scoped to
# write PR labels/comments on fork PRs (the standard `pull_request` token is
# read-only for forks). This also means the job MUST NOT check out PR code —
# see the inline warning in the trigger block below.
#
# Maintainer bypass: add the `bypass-fork-main-check` label to the PR.

name: Block fork main PRs

on:
  pull_request_target:
    # NEVER CHECK OUT UNTRUSTED CODE FROM A PR's HEAD IN A pull_request_target JOB.
    # Doing so would allow attackers to execute arbitrary code in the context of your repository.
    types: [opened, reopened, synchronize, labeled, unlabeled]

permissions:
  contents: read

jobs:
  guard:
    if: >-
      github.repository_owner == 'langchain-ai' &&
      github.event.pull_request.head.repo.fork == true &&
      (github.event.pull_request.head.ref == 'main' || github.event.pull_request.head.ref == 'master') &&
      !contains(github.event.pull_request.labels.*.name, 'bypass-fork-main-check')
    runs-on: ubuntu-latest
    permissions:
      pull-requests: write
    steps:
      - name: Close PR and post guidance
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.payload.pull_request.number;
            const headRef = context.payload.pull_request.head.ref;
            const marker = '<!-- block-fork-main -->';

            // Ensure the warning label exists and apply it
            const labelName = 'fork-main-head';
            try {
              await github.rest.issues.getLabel({ owner, repo, name: labelName });
            } catch (e) {
              if (e.status !== 404) {
                throw new Error(`getLabel(${labelName}) failed: ${e.message}`);
              }
              try {
                await github.rest.issues.createLabel({
                  owner, repo, name: labelName, color: 'b76e79',
                });
              } catch (createErr) {
                // A 422 with code `already_exists` means a race created the
                // label between getLabel and createLabel — safe to ignore.
                // Any other 422 (bad color, name too long) indicates a real
                // bug introduced by editing this step, so rethrow.
                const alreadyExists =
                  createErr.status === 422 &&
                  Array.isArray(createErr.errors) &&
                  createErr.errors.some(e => e.code === 'already_exists');
                if (!alreadyExists) throw createErr;
              }
            }
            await github.rest.issues.addLabels({
              owner, repo, issue_number: prNumber, labels: [labelName],
            });

            const defaultBranch = context.payload.repository.default_branch;
            const lines = [
              marker,
              `**This PR has been automatically closed** because its head branch is \`${headRef}\` on a fork.`,
              '',
              'PRs opened from a fork\'s `main` (or `master`) branch can produce a `Merge branch \'main\' into main` commit on the source side. Under an admin merge override that commit can land directly on this repo\'s default branch, bypassing the squash-only policy and polluting the changelog.',
              '',
              'To fix:',
              `1. Sync your fork's \`${defaultBranch}\` first (\`git fetch upstream && git switch ${defaultBranch} && git merge --ff-only upstream/${defaultBranch}\`)`,
              '2. Create a feature branch: `git switch -c feat/my-change`',
              '3. Push it: `git push -u origin feat/my-change`',
              `4. Open a new PR from \`feat/my-change\` → \`langchain-ai/langchain:${defaultBranch}\``,
              '',
              '*Maintainers: add the `bypass-fork-main-check` label to override.*',
            ];
            const body = lines.join('\n');

            // Dedup: update existing marker comment instead of stacking.
            const comments = await github.paginate(
              github.rest.issues.listComments,
              { owner, repo, issue_number: prNumber, per_page: 100 },
            );
            const existing = comments.find(c => c.body && c.body.includes(marker));

            if (!existing) {
              await github.rest.issues.createComment({
                owner, repo, issue_number: prNumber, body,
              });
            } else if (existing.body !== body) {
              await github.rest.issues.updateComment({
                owner, repo, comment_id: existing.id, body,
              });
            }

            if (context.payload.pull_request.state === 'open') {
              await github.rest.pulls.update({
                owner, repo, pull_number: prNumber, state: 'closed',
              });
            }

            // Cancel still-queued/in-progress checks on this PR head.
            // Best-effort: new runs may still queue after this loop (e.g., other
            // pull_request triggers fanning out). The PR is already closed above,
            // so leftover runs are wasted compute, not a correctness issue.
            // We track the cancel ratio so a wholesale failure (token-scope
            // regression making EVERY cancel return 403) is surfaced rather
            // than silently producing N warnings + green job.
            const headSha = context.payload.pull_request.head.sha;
            let attempted = 0;
            let cancelled = 0;
            for (const status of ['in_progress', 'queued']) {
              const runs = await github.paginate(
                github.rest.actions.listWorkflowRunsForRepo,
                { owner, repo, head_sha: headSha, status, per_page: 100 },
              );
              for (const run of runs) {
                if (run.id === context.runId) continue;
                attempted++;
                try {
                  await github.rest.actions.cancelWorkflowRun({
                    owner, repo, run_id: run.id,
                  });
                  cancelled++;
                } catch (err) {
                  core.warning(`Could not cancel run ${run.id}: ${err.message}`);
                }
              }
            }
            if (attempted > 0 && cancelled === 0) {
              core.warning(`Attempted to cancel ${attempted} run(s) on head ${headSha} but none succeeded — check token scope.`);
            }

            core.setFailed(`PR head ref is \`${headRef}\` on a fork — open from a feature branch instead.`);

name: Dev Release

# Called by publish.yml (the npm Trusted Publisher entry point)
on:
  workflow_call:
    inputs:
      npm_tag:
        description: "NPM tag for the release"
        required: false
        default: "dev"
        type: string

permissions:
  contents: read

env:
  CI: true

jobs:
  release:
    name: Dev Release
    if: github.repository == 'langchain-ai/langchainjs'
    runs-on: ubuntu-latest
    permissions:
      contents: read
      id-token: write
      pull-requests: write
    steps:
      - name: ⬇️ Checkout repo
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          fetch-depth: 0

      - name: 📦 Setup pnpm
        uses: pnpm/action-setup@0977fd99725f1db4007ccb2928dbb4e90d06cc86 # v6.0.10

      - name: ⎔ Setup node
        uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020 # v7.0.0
        with:
          node-version-file: ".nvmrc"
          cache: "pnpm"

      - name: 📥 Install deps
        run: pnpm install --frozen-lockfile

      - name: 🔍 Check for changesets
        id: changesets
        run: |
          # Check if there are any changeset files (excluding README.md)
          CHANGESET_COUNT=$(find .changeset -name "*.md" ! -name "README.md" | wc -l | tr -d ' ')
          echo "count=$CHANGESET_COUNT" >> $GITHUB_OUTPUT
          if [ "$CHANGESET_COUNT" -eq 0 ]; then
            echo "::error::No changesets found. Please add a changeset before running a dev release."
            echo "::error::Run 'pnpm changeset' to create a changeset for your changes."
            exit 1
          fi
          echo "Found $CHANGESET_COUNT changeset(s)"

      - name: 🧹 Prepare for snapshot release
        run: |
          # Disable changelog generation for snapshot releases
          # Enable useCalculatedVersion to preserve current version (e.g., 1.2.0-dev-xxx instead of 0.0.0-dev-xxx)
          pnpm dlx json -I -f .changeset/config.json -e "this.changelog = false; this.snapshot = { useCalculatedVersion: true, prereleaseTemplate: '{tag}-{timestamp}' }"

      - name: 📦 Version packages (snapshot)
        id: version
        run: |
          # Version all packages with changesets using snapshot mode
          # This will also update internal dependencies automatically
          OUTPUT=$(pnpm changeset version --snapshot ${{ inputs.npm_tag }} 2>&1) || true
          echo "$OUTPUT"
          if echo "$OUTPUT" | grep -q "No unreleased changesets found"; then
            echo "success=0" >> $GITHUB_OUTPUT
          else
            echo "success=1" >> $GITHUB_OUTPUT
          fi

      - name: 📥 Reinstall deps after versioning
        if: steps.version.outputs.success == '1'
        run: |
          # Re-run install to update workspace links after changeset version modified package.json files
          # This ensures pnpm pack can resolve workspace:* protocols correctly during build validation
          pnpm install --no-frozen-lockfile

      - name: 🔨 Build packages
        if: steps.version.outputs.success == '1'
        run: |
          # Build all packages (turbo will handle dependency order)
          pnpm run build

      - name: 🔐 Setup npm auth
        if: steps.version.outputs.success == '1'
        run: |
          echo "registry=https://registry.npmjs.org" >> ~/.npmrc
          echo "//registry.npmjs.org/:_authToken=${{ secrets.NPM_TOKEN }}" >> ~/.npmrc

      - name: 🚀 Publish to npm
        if: steps.version.outputs.success == '1'
        run: |
          # Only publish packages with snapshot versions (ignore pending regular releases)
          echo "🔍 Searching for packages to publish..."
          echo "📋 Looking for versions containing: -${{ inputs.npm_tag }}-"

          PUBLISHED_COUNT=0
          SKIPPED_COUNT=0

          for pkg_json in $(find libs -name "package.json" -not -path "*/node_modules/*"); do
            version=$(jq -r '.version' "$pkg_json")
            name=$(jq -r '.name' "$pkg_json")
            private=$(jq -r '.private // false' "$pkg_json")

            if [[ "$private" == "true" ]]; then
              echo "⏭️  Skipping $name (private package)"
              continue
            fi

            if [[ "$version" == *"-${{ inputs.npm_tag }}-"* ]]; then
              echo "📦 Publishing $name@$version"
              dir=$(dirname "$pkg_json")
              (cd "$dir" && pnpm publish --tag ${{ inputs.npm_tag }} --no-git-checks --access public)
              PUBLISHED_COUNT=$((PUBLISHED_COUNT + 1))
            else
              echo "⏭️  Skipping $name@$version (no snapshot suffix)"
              SKIPPED_COUNT=$((SKIPPED_COUNT + 1))
            fi
          done

          echo ""
          echo "✅ Published: $PUBLISHED_COUNT packages"
          echo "⏭️  Skipped: $SKIPPED_COUNT packages"

          if [[ "$PUBLISHED_COUNT" -eq 0 ]]; then
            echo "::warning::No packages with snapshot versions were found to publish"
          fi
        env:
          NPM_TOKEN: ${{ secrets.NPM_TOKEN }}
          NPM_CONFIG_PROVENANCE: true

      - name: 📋 Get published packages
        if: steps.version.outputs.success == '1' && github.ref != 'refs/heads/main'
        id: published
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const fs = require('fs');
            const path = require('path');

            // Find all package.json files in libs directory using built-in fs
            const libsDir = path.join(process.cwd(), 'libs');
            const allFiles = fs.readdirSync(libsDir, { recursive: true });
            const files = allFiles
              .filter(f => f.endsWith('package.json') && !f.includes('node_modules'))
              .map(f => path.join(libsDir, f));

            const tag = '${{ inputs.npm_tag }}';
            const packages = [];

            for (const file of files) {
              try {
                const content = fs.readFileSync(file, 'utf8');
                const pkg = JSON.parse(content);

                // Check if this package has a snapshot version
                if (pkg.version && pkg.version.includes(`-${tag}`)) {
                  packages.push({
                    name: pkg.name,
                    version: pkg.version
                  });
                }
              } catch (e) {
                // Skip files that can't be parsed
              }
            }

            if (packages.length === 0) {
              console.log('No packages with snapshot versions found');
              core.setOutput('packages', '[]');
              core.setOutput('count', '0');
              return;
            }

            // Sort packages alphabetically
            packages.sort((a, b) => a.name.localeCompare(b.name));

            console.log(`Found ${packages.length} published package(s):`);
            packages.forEach(p => console.log(`  - ${p.name}@${p.version}`));

            core.setOutput('packages', JSON.stringify(packages));
            core.setOutput('count', packages.length.toString());

            // Write to step summary
            const summary = core.summary
              .addHeading('📦 Published Packages', 3)
              .addTable([
                [{data: 'Package', header: true}, {data: 'Version', header: true}],
                ...packages.map(p => [p.name, `\`${p.version}\``])
              ])
              .addHeading('Install', 4)
              .addCodeBlock(
                packages.map(p => `npm i ${p.name}@${p.version} --save-exact`).join('\n'),
                'sh'
              );

            await summary.write();

      - name: 💬 Comment on PR
        if: steps.version.outputs.success == '1' && steps.published.outputs.count != '0' && github.ref != 'refs/heads/main'
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            // Get the current branch name
            const branch = context.ref.replace('refs/heads/', '');

            // Find open PRs where this branch is the head
            const { data: prs } = await github.rest.pulls.list({
              owner: context.repo.owner,
              repo: context.repo.repo,
              state: 'open',
              head: `${context.repo.owner}:${branch}`
            });

            if (prs.length === 0) {
              console.log(`No open PRs found for branch: ${branch}`);
              return;
            }

            const packages = JSON.parse('${{ steps.published.outputs.packages }}');
            const run_url = `${{ github.server_url }}/${{ github.repository }}/actions/runs/${{ github.run_id }}`;

            // Build the package table
            const tableRows = packages.map(p => `| ${p.name} | \`${p.version}\` |`).join('\n');

            // Build install commands
            const packageVersions = packages.map(p => `${p.name}@${p.version}`).join(' ');

            const body = `## 📦 Dev Release Published

            A dev release has been published for this PR!

            | Package | Version |
            | --- | --- |
            ${tableRows}

            **Install:**
            \`\`\`sh
            npm i ${packageVersions} --save-exact
            \`\`\`

            [View workflow run](${run_url})`;

            // Comment on each PR
            for (const pr of prs) {
              console.log(`Commenting on PR #${pr.number}`);
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: pr.number,
                body: body.split('\n').map(line => line.trim()).join('\n')
              });
            }

name: Label issues
on:
  issues:
    types:
      - reopened
      - opened

jobs:
  label_issues:
    name: "Issue: add labels"
    if: ${{ github.event.action == 'opened' || github.event.action == 'reopened' }}
    runs-on: ubuntu-latest
    environment: github-app-auth
    permissions:
      contents: read
      id-token: write
    steps:
      - name: Checkout GitHub automation
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          sparse-checkout: .github/actions/github-app-token
          fetch-depth: 1
          persist-credentials: false

      - name: Get GitHub automation token
        id: github-auth
        uses: ./.github/actions/github-app-token
        with:
          mode: ${{ vars.GH_APP_AUTH_MODE }}
          azure-client-id: ${{ secrets.GH_APP_AZURE_CLIENT_ID }}
          azure-tenant-id: ${{ secrets.GH_APP_AZURE_TENANT_ID }}
          azure-subscription-id: ${{ secrets.GH_APP_AZURE_SUBSCRIPTION_ID }}
          key-vault-name: ${{ secrets.GH_APP_KEY_VAULT_NAME }}
          key-name: ${{ secrets.GH_APP_KEY_NAME }}
          github-app-client-id: ${{ secrets.GH_APP_CLIENT_ID }}
          github-app-installation-id: ${{ secrets.GH_APP_INSTALLATION_ID }}
          repository: ${{ github.repository }}
          permission-profile: issues
          fallback-token: ${{ secrets.GH_ACTIONS_PR_WRITE }}

      - uses: actions/github-script@ed597411d8f924073f98dfc5c65a23a2325f34cd # v8.0.0
        with:
          github-token: ${{ steps.github-auth.outputs.token }}
          script: |
            // Get the issue body and title
            const body = context.payload.issue.body
            let title = context.payload.issue.title

            // Define the labels array
            let labels = ["triage"]

            // Check if the body or the title contains the word 'python' (case-insensitive)
            if ((body != null && body.match(/python/i)) || (title != null && title.match(/python/i))) {
              // Add the 'python' label to the array
              labels.push("python")
            }

            // Check if the body or the title contains the word 'java' (case-insensitive)
            if ((body != null && body.match(/java/i)) || (title != null && title.match(/java/i))) {
              // Add the 'java' label to the array
              labels.push("java")
            }

            // Check if the body or the title contains the words 'dotnet', '.net', 'c#' or 'csharp' (case-insensitive)
            if ((body != null && body.match(/.net/i)) || (title != null && title.match(/.net/i)) ||
                (body != null && body.match(/dotnet/i)) || (title != null && title.match(/dotnet/i)) ||
                (body != null && body.match(/C#/i)) || (title != null && title.match(/C#/i)) ||
                (body != null && body.match(/csharp/i)) || (title != null && title.match(/csharp/i))) {
              // Add the '.NET' label to the array
              labels.push(".NET")
            }

            // Add the labels to the issue
            github.rest.issues.addLabels({
              issue_number: context.issue.number,
              owner: context.repo.owner,
              repo: context.repo.repo,
              labels: labels
            });

name: Label title prefix
on:
  issues:
    types: [labeled]
  pull_request_target:
    types: [labeled]

jobs:
  add_title_prefix:
    name: "Issue/PR: add title prefix"
    continue-on-error: true
    runs-on: ubuntu-latest
    permissions:
      issues: write
      pull-requests: write

    steps:
      - uses: actions/github-script@ed597411d8f924073f98dfc5c65a23a2325f34cd # v8.0.0
        name: "Issue/PR: update title"
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            let prefixLabels = {
              "python": "Python",
              "java": "Java",
              ".NET": ".Net"
            };

            function addTitlePrefix(title, prefix)
            {
              // Update the title based on the label and prefix
              // Check if the title starts with the prefix (case-sensitive)
              if (!title.startsWith(prefix + ": ")) {
                // If not, check if the first word is the label (case-insensitive)
                if (title.match(new RegExp(`^${prefix}`, 'i'))) {
                  // If yes, replace it with the prefix (case-sensitive)
                  title = title.replace(new RegExp(`^${prefix}`, 'i'), prefix);
                } else {
                  // If not, prepend the prefix to the title
                  title = prefix + ": " + title;
                }
              }

              return title;
            }

            labelAdded = context.payload.label.name

            // Check if the issue or PR has the label
            if (labelAdded in prefixLabels) {
              let prefix = prefixLabels[labelAdded];
              switch(context.eventName) {
                case 'issues':
                  github.rest.issues.update({
                    issue_number: context.issue.number,
                    owner: context.repo.owner,
                    repo: context.repo.repo,
                    title: addTitlePrefix(context.payload.issue.title, prefix)
                  });
                  break

                case 'pull_request_target':
                  github.rest.pulls.update({
                    pull_number: context.issue.number,
                    owner: context.repo.owner,
                    repo: context.repo.repo,
                    title: addTitlePrefix(context.payload.pull_request.title, prefix)
                  });
                  break
                default:
                  core.setFailed('Unrecognited eventName: ' + context.eventName);
              }
            }

name: README PR Check

on:
  # pull_request_target, not pull_request: fork PRs get a read-only token under
  # pull_request, so the label and comment calls fail with 403. This job only
  # calls the API and never checks out PR code, so the write token is safe.
  pull_request_target:
    types: [opened]
    paths:
      - 'README.md'
  issue_comment:
    types: [created]

jobs:
  check-readme-only:
    if: github.event_name == 'pull_request_target'
    runs-on: ubuntu-latest
    permissions:
      contents: read
      pull-requests: write
    steps:
      - name: Check files and comment if README-only
        uses: actions/github-script@v8
        with:
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.payload.pull_request.number;

            const { data: files } = await github.rest.pulls.listFiles({ owner, repo, pull_number: prNumber });

            if (files.length !== 1 || files[0].filename !== 'README.md') {
              console.log('PR modifies files other than README, skipping');
              return;
            }

            // Check if we've already commented
            const { data: comments } = await github.rest.issues.listComments({ owner, repo, issue_number: prNumber });
            if (comments.some(c => c.user.login === 'github-actions[bot]' && c.body.includes('no longer accepting PRs to add new servers'))) {
              console.log('Already commented on this PR, skipping');
              return;
            }

            await github.rest.issues.addLabels({ owner, repo, issue_number: prNumber, labels: ['readme: pending'] });

            await github.rest.issues.createComment({
              owner,
              repo,
              issue_number: prNumber,
              body: [
                'Thanks for your contribution!',
                '',
                '**We are no longer accepting PRs to add new servers to the README.** The third-party server list has been removed from this README in favor of the [MCP Server Registry](https://registry.modelcontextprotocol.io/).',
                '',
                '👉 **To add a new MCP server:** Please publish it to the [MCP Server Registry](https://github.com/modelcontextprotocol/registry) instead. You can browse published servers at [registry.modelcontextprotocol.io](https://registry.modelcontextprotocol.io/).',
                '',
                '👉 **If this PR updates or removes an existing entry:** We do still accept these changes. Please reply with `/i-promise-this-is-not-a-new-server` to continue.',
                '',
                'If this PR is adding a new server, please close it and submit to the registry instead.',
              ].join('\n'),
            });

  handle-confirmation:
    if: github.event_name == 'issue_comment' && github.event.issue.pull_request && contains(github.event.comment.body, '/i-promise-this-is-not-a-new-server')
    runs-on: ubuntu-latest
    permissions:
      pull-requests: write
    steps:
      - name: Swap labels and minimize comments
        uses: actions/github-script@v8
        with:
          script: |
            const { owner, repo } = context.repo;
            const prNumber = context.payload.issue.number;

            // Check if pending label exists
            const { data: labels } = await github.rest.issues.listLabelsOnIssue({ owner, repo, issue_number: prNumber });
            if (!labels.some(l => l.name === 'readme: pending')) {
              console.log('No pending label found, skipping');
              return;
            }

            // Swap labels
            try {
              await github.rest.issues.removeLabel({ owner, repo, issue_number: prNumber, name: 'readme: pending' });
            } catch (e) {}
            await github.rest.issues.addLabels({ owner, repo, issue_number: prNumber, labels: ['readme: ready for review'] });

            // Find the bot's original comment
            const { data: comments } = await github.rest.issues.listComments({ owner, repo, issue_number: prNumber });
            const botComment = comments.find(c =>
              c.user.login === 'github-actions[bot]' &&
              c.body.includes('no longer accepting PRs to add new servers')
            );

            // Minimize both comments via GraphQL
            const minimizeComment = async (nodeId) => {
              await github.graphql(`
                mutation($id: ID!) {
                  minimizeComment(input: {subjectId: $id, classifier: RESOLVED}) {
                    minimizedComment { isMinimized }
                  }
                }
              `, { id: nodeId });
            };

            if (botComment) {
              await minimizeComment(botComment.node_id);
            }

            // Only minimize user's comment if it's just the command
            const userComment = context.payload.comment.body.trim();
            if (userComment === '/i-promise-this-is-not-a-new-server') {
              await minimizeComment(context.payload.comment.node_id);
            }

# This workflow makes sure contributors don't forget to add a changelog entry or explicitly opt-out of it.
#
# Do not extend this workflow to include checking out the code (e.g. for building and testing purposes) while the pull_request_target trigger is used.
# Instead, see use of workflow_run in https://securitylab.github.com/resources/github-actions-preventing-pwn-requests/

name: Enforce Changelog

on:
    # The pull_request_target trigger event allows PRs raised from forks to have write permissions and access secrets.
    # We uses it in this workflow to enable writing comments to the PR.
    pull_request_target:
        types:
            - opened
            - ready_for_review
            - reopened
            - synchronize
            - labeled
            - unlabeled

# This workflow runs for not-yet-reviewed external contributions.
# Following a pull_request_target trigger the workflow would have write permissions,
# so we intentionally restrict the permissions to only include write access on pull-requests.
permissions:
    contents: read
    pull-requests: write

jobs:
    # Check target branch of the PR to determine if a changelog is needed and what version folder it should exist in
    check-changelog-entry:
        if: ${{ !contains(github.event.pull_request.labels.*.name, 'skip-changelog-check') }}
        name: "Check Changelog Entry"
        runs-on: ubuntu-latest
        concurrency:
            group: changelog-${{ github.head_ref }}
            cancel-in-progress: true

        steps:
            - name: "Changed files"
              uses: dorny/paths-filter@ceb8a2b8f2d89434be7ff52d3de7ec3738c5cc9d # v4.0.3
              id: changelog
              with:
                  filters: |
                      changes:
                          - '.changes/*/*.yaml'
                      changelog:
                        - 'CHANGELOG.md'
                      version:
                        - 'version/VERSION'
                  list-files: json

            - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
              with:
                  sparse-checkout: |
                      version/VERSION
                  sparse-checkout-cone-mode: false
                  ref: ${{ github.base_ref }} # Base ref refers to the target branch of this PR

            - name: "Check for changelog entry"
              uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
              with:
                  script: |
                      const fs = require("fs");
                      async function createOrUpdateChangelogComment(commentDetails, deleteComment) {
                          const commentStart = "## Changelog Warning"

                          const body = commentStart + "\n\n" + commentDetails;
                          const { number: issue_number } = context.issue;
                          const { owner, repo } = context.repo;

                          // List all comments
                          const allComments = (await github.rest.issues.listComments({
                              issue_number,
                              owner,
                              repo,
                          })).data;

                          const existingComment = allComments.find(c => c.body.startsWith(commentStart));
                          const comment_id = existingComment?.id;

                          if (deleteComment) {
                              if (existingComment) {
                                  await github.rest.issues.deleteComment({
                                      owner,
                                      repo,
                                      comment_id,
                                  });
                              }
                              return;
                          }

                          core.setFailed(commentDetails);

                          if (existingComment) {
                              await github.rest.issues.updateComment({
                                  owner,
                                  repo,
                                  comment_id,
                                  body,
                              });
                          } else {
                              await github.rest.issues.createComment({
                                  owner,
                                  repo,
                                  issue_number,
                                  body,
                              });
                          }
                      }

                      const changesPresent = ${{steps.changelog.outputs.changes}};
                      const changedChangesFiles = ${{steps.changelog.outputs.changes_files}};
                      const changelogChangesPresent = ${{steps.changelog.outputs.changelog}};
                      const versionChangesPresent = ${{steps.changelog.outputs.version}};

                      const prLabels = await github.rest.issues.listLabelsOnIssue({
                          issue_number: context.issue.number,
                          owner: context.repo.owner,
                          repo: context.repo.repo
                      });
                      const backportLabels = prLabels.data.filter(label => label.name.endsWith("-backport"));
                      const backportVersions = backportLabels.map(label => label.name.split("-")[0]);

                      const currentVersionFile = fs.readFileSync("./version/VERSION", "utf-8");
                      const currentVersionParts = currentVersionFile.split(".");
                      currentVersionParts.pop();
                      const currentVersion = currentVersionParts.join(".");

                      const allVersions = [currentVersion, ...backportVersions]
                      allVersions.sort((a, b) => {
                        const as = a.split(".").map(Number);
                        const bs = b.split(".").map(Number);

                        if (as[0] !== bs[0]) {
                          return as[0] - bs[0];
                        }

                        if (as[1] !== bs[1]) {
                          return as[1] - bs[1];
                        }
                      });

                      const noChangelogNeededLabel = prLabels.data.find(label => label.name === 'no-changelog-needed');
                      const dependenciesLabel = prLabels.data.find(label => label.name === 'dependencies');

                      // We want to prohibit contributors from directly changing the CHANGELOG.md, it's 
                      // generated so all changes will be lost during the release process.
                      // Therefore we only allow the changelog to change together with the version.
                      // In very rare cases where we generate changes in the changelog without changing the 
                      // version we will just ignore this failing check.
                      if (changelogChangesPresent && !versionChangesPresent) {
                          await createOrUpdateChangelogComment("Please don't edit the CHANGELOG.md manually. We use changie to control the Changelog generation, please use `npx changie new` to create a new changelog entry.");
                          return;
                      }

                      if (dependenciesLabel) {
                          return;
                      }

                      if (noChangelogNeededLabel) {
                          if (changesPresent) {
                              await createOrUpdateChangelogComment("Please remove either the 'no-changelog-needed' label or the changelog entry from this PR.");
                              return;
                          }

                          // Nothing to complain about, so delete any existing comment
                          await createOrUpdateChangelogComment("", true);
                          return;
                      }

                      // We only want to have a changelog entry for the oldest version this PR will
                      // land in.
                      const onlyExpectedChangeVersion = allVersions[0]
                      const missingChangelogEntry = !changedChangesFiles.some(filePath => filePath.includes("/v"+onlyExpectedChangeVersion+"/"))
                      const unexpectedChangelogEntry = changedChangesFiles.filter(filePath => !filePath.includes("/v"+onlyExpectedChangeVersion+"/"))


                      if (missingChangelogEntry) {
                          await createOrUpdateChangelogComment(`Currently this PR would target a v${onlyExpectedChangeVersion} release. Please add a changelog entry for in the .changes/v${onlyExpectedChangeVersion} folder, or discuss which release you'd like to target with your reviewer. If you believe this change does not need a changelog entry, please add the 'no-changelog-needed' label.`);
                          return;
                      }

                      if (unexpectedChangelogEntry.length > 0) {
                          await createOrUpdateChangelogComment(`Please remove the changelog entry for the following paths: ${unexpectedChangelogEntry.join(", ")}. If you believe this change does not need a changelog entry, please add the 'no-changelog-needed' label.`);
                          return;
                      }

                      // Nothing to complain about, so delete any existing comment
                      await createOrUpdateChangelogComment("", true);

name: Auto-detect duplicate issues

# yamllint disable-line rule:truthy
on:
  issues:
    types: [labeled]

permissions: {}

concurrency:
  group: ${{ github.workflow }}-${{ github.event.issue.number }}

jobs:
  detect-duplicates:
    name: Detect duplicate issues
    runs-on: ubuntu-latest
    permissions:
      issues: write # To comment on and label issues
      models: read # For AI-based duplicate detection

    steps:
      - name: Check if integration label was added and extract details
        id: extract
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            // Debug: Log the event payload
            console.log('Event name:', context.eventName);
            console.log('Event action:', context.payload.action);
            console.log('Event payload keys:', Object.keys(context.payload));

            // Check the specific label that was added
            const addedLabel = context.payload.label;
            if (!addedLabel) {
              console.log('No label found in labeled event payload');
              core.setOutput('should_continue', 'false');
              return;
            }

            console.log(`Label added: ${addedLabel.name}`);

            if (!addedLabel.name.startsWith('integration:')) {
              console.log('Added label is not an integration label, skipping duplicate detection');
              core.setOutput('should_continue', 'false');
              return;
            }

            console.log(`Integration label added: ${addedLabel.name}`);

            let currentIssue;
            let integrationLabels = [];

            try {
              const issue = await github.rest.issues.get({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.payload.issue.number
              });

              currentIssue = issue.data;

              // Check if potential-duplicate label already exists
              const hasPotentialDuplicateLabel = currentIssue.labels
                .some(label => label.name === 'potential-duplicate');

              if (hasPotentialDuplicateLabel) {
                console.log('Issue already has potential-duplicate label, skipping duplicate detection');
                core.setOutput('should_continue', 'false');
                return;
              }

              integrationLabels = currentIssue.labels
                .filter(label => label.name.startsWith('integration:'))
                .map(label => label.name);
            } catch (error) {
              core.error(`Failed to fetch issue #${context.payload.issue.number}:`, error.message);
              core.setOutput('should_continue', 'false');
              return;
            }

            // Check if we've already posted a duplicate detection comment recently
            let comments;
            try {
              comments = await github.rest.issues.listComments({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.payload.issue.number,
                per_page: 10
              });
            } catch (error) {
              core.error('Failed to fetch comments:', error.message);
              // Continue anyway, worst case we might post a duplicate comment
              comments = { data: [] };
            }

            // Check if we've already posted a duplicate detection comment
            const recentDuplicateComment = comments.data.find(comment =>
              comment.user && comment.user.login === 'github-actions[bot]' &&
              comment.body.includes('<!-- workflow: detect-duplicate-issues -->')
            );

            if (recentDuplicateComment) {
              console.log('Already posted duplicate detection comment, skipping');
              core.setOutput('should_continue', 'false');
              return;
            }

            core.setOutput('should_continue', 'true');
            core.setOutput('current_number', currentIssue.number);
            core.setOutput('current_title', currentIssue.title);
            core.setOutput('current_body', currentIssue.body);
            core.setOutput('current_url', currentIssue.html_url);
            core.setOutput('integration_labels', JSON.stringify(integrationLabels));

            console.log(`Current issue: #${currentIssue.number}`);
            console.log(`Integration labels: ${integrationLabels.join(', ')}`);

      - name: Fetch similar issues
        id: fetch_similar
        if: steps.extract.outputs.should_continue == 'true'
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          INTEGRATION_LABELS: ${{ steps.extract.outputs.integration_labels }}
          CURRENT_NUMBER: ${{ steps.extract.outputs.current_number }}
        with:
          script: |
            const integrationLabels = JSON.parse(process.env.INTEGRATION_LABELS);
            const currentNumber = parseInt(process.env.CURRENT_NUMBER);

            if (integrationLabels.length === 0) {
              console.log('No integration labels found, skipping duplicate detection');
              core.setOutput('has_similar', 'false');
              return;
            }

            // Use GitHub search API to find issues with matching integration labels
            console.log(`Searching for issues with integration labels: ${integrationLabels.join(', ')}`);

            // Build search query for issues with any of the current integration labels
            const labelQueries = integrationLabels.map(label => `label:"${label}"`);

            // Calculate date 6 months ago
            const sixMonthsAgo = new Date();
            sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - 6);
            const dateFilter = `created:>=${sixMonthsAgo.toISOString().split('T')[0]}`;

            let searchQuery;

            if (labelQueries.length === 1) {
              searchQuery = `repo:${context.repo.owner}/${context.repo.repo} is:issue ${labelQueries[0]} ${dateFilter}`;
            } else {
              searchQuery = `repo:${context.repo.owner}/${context.repo.repo} is:issue (${labelQueries.join(' OR ')}) ${dateFilter}`;
            }

            console.log(`Search query: ${searchQuery}`);

            let result;
            try {
              result = await github.rest.search.issuesAndPullRequests({
                q: searchQuery,
                per_page: 15,
                sort: 'updated',
                order: 'desc'
              });
            } catch (error) {
              core.error('Failed to search for similar issues:', error.message);
              if (error.status === 403 && error.message.includes('rate limit')) {
                core.error('GitHub API rate limit exceeded');
              }
              core.setOutput('has_similar', 'false');
              return;
            }

            // Filter out the current issue, pull requests, and newer issues (higher numbers)
            const similarIssues = result.data.items
              .filter(item =>
                item.number !== currentNumber &&
                !item.pull_request &&
                item.number < currentNumber // Only include older issues (lower numbers)
              )
              .map(item => ({
                number: item.number,
                title: item.title,
                body: item.body,
                url: item.html_url,
                state: item.state,
                createdAt: item.created_at,
                updatedAt: item.updated_at,
                comments: item.comments,
                labels: item.labels.map(l => l.name)
              }));

            console.log(`Found ${similarIssues.length} issues with matching integration labels`);
            console.log('Raw similar issues:', JSON.stringify(similarIssues.slice(0, 3), null, 2));

            if (similarIssues.length === 0) {
              console.log('No similar issues found, setting has_similar to false');
              core.setOutput('has_similar', 'false');
              return;
            }

            console.log('Similar issues found, setting has_similar to true');
            core.setOutput('has_similar', 'true');

            // Clean the issue data to prevent JSON parsing issues
            const cleanedIssues = similarIssues.slice(0, 15).map(item => {
              // Handle body with improved truncation and null handling
              let cleanBody = '';
              if (item.body && typeof item.body === 'string') {
                // Remove control characters
                const cleaned = item.body.replace(/[\u0000-\u001F\u007F-\u009F]/g, '');
                // Truncate to 1000 characters and add ellipsis if needed
                cleanBody = cleaned.length > 1000
                  ? cleaned.substring(0, 1000) + '...'
                  : cleaned;
              }

              return {
                number: item.number,
                title: item.title.replace(/[\u0000-\u001F\u007F-\u009F]/g, ''), // Remove control characters
                body: cleanBody,
                url: item.url,
                state: item.state,
                createdAt: item.createdAt,
                updatedAt: item.updatedAt,
                comments: item.comments,
                labels: item.labels
              };
            });

            console.log(`Cleaned issues count: ${cleanedIssues.length}`);
            console.log('First cleaned issue:', JSON.stringify(cleanedIssues[0], null, 2));

            core.setOutput('similar_issues', JSON.stringify(cleanedIssues));

      - name: Detect duplicates using AI
        id: ai_detection
        if: steps.extract.outputs.should_continue == 'true' && steps.fetch_similar.outputs.has_similar == 'true'
        uses: actions/ai-inference@a7805884c80886efc241e94a5351df715968a0ad # v2.1.1
        with:
          model: openai/gpt-4o
          system-prompt: |
            You are a Home Assistant issue duplicate detector. Your task is to identify TRUE DUPLICATES - issues that report the EXACT SAME problem, not just similar or related issues.

            CRITICAL: An issue is ONLY a duplicate if:
            - It describes the SAME problem with the SAME root cause
            - Issues about the same integration but different problems are NOT duplicates
            - Issues with similar symptoms but different causes are NOT duplicates

            Important considerations:
            - Open issues are more relevant than closed ones for duplicate detection
            - Recently updated issues may indicate ongoing work or discussion
            - Issues with more comments are generally more relevant and active
            - Older closed issues might be resolved differently than newer approaches
            - Consider the time between issues - very old issues may have different contexts

            Rules:
            1. ONLY mark as duplicate if the issues describe IDENTICAL problems
            2. Look for issues that report the same problem or request the same functionality
            3. Different error messages = NOT a duplicate (even if same integration)
            4. For CLOSED issues, only mark as duplicate if they describe the EXACT same problem
            5. For OPEN issues, use a lower threshold (90%+ similarity)
            6. Prioritize issues with higher comment counts as they indicate more activity/relevance
            7. When in doubt, do NOT mark as duplicate
            8. Return ONLY a JSON array of issue numbers that are duplicates
            9. If no duplicates are found, return an empty array: []
            10. Maximum 5 potential duplicates, prioritize open issues with comments
            11. Consider the age of issues - prefer recent duplicates over very old ones

            Example response format:
            [1234, 5678, 9012]

          prompt: |
            Current issue (just created):
            Title: ${{ steps.extract.outputs.current_title }}
            Body: ${{ steps.extract.outputs.current_body }}

            Other issues to compare against (each includes state, creation date, last update, and comment count):
            ${{ steps.fetch_similar.outputs.similar_issues }}

            Analyze these issues and identify which ones describe IDENTICAL problems and thus are duplicates of the current issue. When sorting them, consider their state (open/closed), how recently they were updated, and their comment count (higher = more relevant).

          max-tokens: 100

      - name: Post duplicate detection results
        id: post_results
        if: steps.extract.outputs.should_continue == 'true' && steps.fetch_similar.outputs.has_similar == 'true'
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          AI_RESPONSE: ${{ steps.ai_detection.outputs.response }}
          SIMILAR_ISSUES: ${{ steps.fetch_similar.outputs.similar_issues }}
        with:
          script: |
            const aiResponse = process.env.AI_RESPONSE;

            console.log('Raw AI response:', JSON.stringify(aiResponse));

            let duplicateNumbers = [];
            try {
              // Clean the response of any potential control characters
              const cleanResponse = aiResponse.trim().replace(/[\u0000-\u001F\u007F-\u009F]/g, '');
              console.log('Cleaned AI response:', cleanResponse);

              duplicateNumbers = JSON.parse(cleanResponse);

              // Ensure it's an array and contains only numbers
              if (!Array.isArray(duplicateNumbers)) {
                console.log('AI response is not an array, trying to extract numbers');
                const numberMatches = cleanResponse.match(/\d+/g);
                duplicateNumbers = numberMatches ? numberMatches.map(n => parseInt(n)) : [];
              }

              // Filter to only valid numbers
              duplicateNumbers = duplicateNumbers.filter(n => typeof n === 'number' && !isNaN(n));

            } catch (error) {
              console.log('Failed to parse AI response as JSON:', error.message);
              console.log('Raw response:', aiResponse);

              // Fallback: try to extract numbers from the response
              const numberMatches = aiResponse.match(/\d+/g);
              duplicateNumbers = numberMatches ? numberMatches.map(n => parseInt(n)) : [];
              console.log('Extracted numbers as fallback:', duplicateNumbers);
            }

            if (!Array.isArray(duplicateNumbers) || duplicateNumbers.length === 0) {
              console.log('No duplicates detected by AI');
              return;
            }

            console.log(`AI detected ${duplicateNumbers.length} potential duplicates: ${duplicateNumbers.join(', ')}`);

            // Get details of detected duplicates
            const similarIssues = JSON.parse(process.env.SIMILAR_ISSUES);
            const duplicates = similarIssues.filter(issue => duplicateNumbers.includes(issue.number));

            if (duplicates.length === 0) {
              console.log('No matching issues found for detected numbers');
              return;
            }

            // Create comment with duplicate detection results
            const duplicateLinks = duplicates.map(issue => `- [#${issue.number}: ${issue.title}](${issue.url})`).join('\n');

            const commentBody = [
              '<!-- workflow: detect-duplicate-issues -->',
              '### 🔍 **Potential duplicate detection**',
              '',
              'I\'ve analyzed similar issues and found the following potential duplicates:',
              '',
              duplicateLinks,
              '',
              '**What to do next:**',
              '1. Please review these issues to see if they match your issue',
              '2. If you find an existing issue that covers your problem:',
              '   - Consider closing this issue',
              '   - Add your findings or 👍 on the existing issue instead',
              '3. If your issue is different or adds new aspects, please clarify how it differs',
              '',
              'This helps keep our issues organized and ensures similar issues are consolidated for better visibility.',
              '',
              '*This message was generated automatically by our duplicate detection system.*'
            ].join('\n');

            try {
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.payload.issue.number,
                body: commentBody
              });

              console.log(`Posted duplicate detection comment with ${duplicates.length} potential duplicates`);

              // Add the potential-duplicate label
              await github.rest.issues.addLabels({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.payload.issue.number,
                labels: ['potential-duplicate']
              });

              console.log('Added potential-duplicate label to the issue');
            } catch (error) {
              core.error('Failed to post duplicate detection comment or add label:', error.message);
              if (error.status === 403) {
                core.error('Permission denied or rate limit exceeded');
              }
              // Don't throw - we've done the analysis, just couldn't post the result
            }

name: Auto-detect non-English issues

# yamllint disable-line rule:truthy
on:
  issues:
    types: [opened]

permissions: {}

concurrency:
  group: ${{ github.workflow }}-${{ github.event.issue.number }}

jobs:
  detect-language:
    name: Detect non-English issues
    runs-on: ubuntu-latest
    permissions:
      issues: write # To comment on, label, and close issues
      models: read # For AI-based language detection

    steps:
      - name: Check issue language
        id: detect_language
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          ISSUE_NUMBER: ${{ github.event.issue.number }}
          ISSUE_TITLE: ${{ github.event.issue.title }}
          ISSUE_BODY: ${{ github.event.issue.body }}
          ISSUE_USER_TYPE: ${{ github.event.issue.user.type }}
        with:
          script: |
            // Get the issue details from environment variables
            const issueNumber = process.env.ISSUE_NUMBER;
            const issueTitle = process.env.ISSUE_TITLE || '';
            const issueBody = process.env.ISSUE_BODY || '';
            const userType = process.env.ISSUE_USER_TYPE;

            // Skip language detection for bot users
            if (userType === 'Bot') {
              console.log('Skipping language detection for bot user');
              core.setOutput('should_continue', 'false');
              return;
            }

            console.log(`Checking language for issue #${issueNumber}`);
            console.log(`Title: ${issueTitle}`);

            // Combine title and body for language detection
            const fullText = `${issueTitle}\n\n${issueBody}`;

            // Check if the text is too short to reliably detect language
            if (fullText.trim().length < 20) {
              console.log('Text too short for reliable language detection');
              core.setOutput('should_continue', 'false'); // Skip processing for very short text
              return;
            }

            core.setOutput('issue_number', issueNumber);
            core.setOutput('issue_text', fullText);
            core.setOutput('should_continue', 'true');

      - name: Detect language using AI
        id: ai_language_detection
        if: steps.detect_language.outputs.should_continue == 'true'
        uses: actions/ai-inference@a7805884c80886efc241e94a5351df715968a0ad # v2.1.1
        with:
          model: openai/gpt-4o-mini
          system-prompt: |
            You are a language detection system. Your task is to determine if the provided text is written in English or another language.

            Rules:
            1. Analyze the text and determine the primary language of the USER'S DESCRIPTION only
            2. IGNORE markdown headers (lines starting with #, ##, ###, etc.) as these are from issue templates, not user input
            3. IGNORE all code blocks (text between ``` or ` markers) as they may contain system-generated error messages in other languages
            4. IGNORE error messages, logs, and system output even if not in code blocks - these often appear in the user's system language
            5. Consider technical terms, code snippets, URLs, and file paths as neutral (they don't indicate non-English)
            6. Focus ONLY on the actual sentences and descriptions written by the user explaining their issue
            7. If the user's explanation/description is in English but includes non-English error messages or logs, consider it ENGLISH
            8. Return ONLY a JSON object with two fields:
               - "is_english": boolean (true if the user's description is primarily in English, false otherwise)
               - "detected_language": string (the name of the detected language, e.g., "English", "Spanish", "Chinese", etc.)
            9. Be lenient - if the user's explanation is in English with non-English system output, it's still English
            10. Common programming terms, error messages, and technical jargon should not be considered as non-English
            11. If you cannot reliably determine the language, set detected_language to "undefined"

            Example response:
            {"is_english": false, "detected_language": "Spanish"}

          prompt: |
            Please analyze the following issue text and determine if it is written in English:

            ${{ steps.detect_language.outputs.issue_text }}

          max-tokens: 50

      - name: Process non-English issues
        if: steps.detect_language.outputs.should_continue == 'true'
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          AI_RESPONSE: ${{ steps.ai_language_detection.outputs.response }}
          ISSUE_NUMBER: ${{ steps.detect_language.outputs.issue_number }}
        with:
          script: |
            const issueNumber = parseInt(process.env.ISSUE_NUMBER);
            const aiResponse = process.env.AI_RESPONSE;

            console.log('AI language detection response:', aiResponse);

            let languageResult;
            try {
              languageResult = JSON.parse(aiResponse.trim());

              // Validate the response structure
              if (!languageResult || typeof languageResult.is_english !== 'boolean') {
                throw new Error('Invalid response structure');
              }
            } catch (error) {
              core.error(`Failed to parse AI response: ${error.message}`);
              console.log('Raw AI response:', aiResponse);

              // Log more details for debugging
              core.warning('Defaulting to English due to parsing error');

              // Default to English if we can't parse the response
              return;
            }

            if (languageResult.is_english) {
              console.log('Issue is in English, no action needed');
              return;
            }

            // If language is undefined or not detected, skip processing
            if (!languageResult.detected_language || languageResult.detected_language === 'undefined') {
              console.log('Language could not be determined, skipping processing');
              return;
            }

            console.log(`Issue detected as non-English: ${languageResult.detected_language}`);

            // Post comment explaining the language requirement
            const commentBody = [
              '<!-- workflow: detect-non-english-issues -->',
              '### 🌐 Non-English issue detected',
              '',
              `This issue appears to be written in **${languageResult.detected_language}** rather than English.`,
              '',
              'The Home Assistant project uses English as the primary language for issues to ensure that everyone in our international community can participate and help resolve issues. This allows any of our thousands of contributors to jump in and provide assistance.',
              '',
              '**What to do:**',
              '1. Re-create the issue using the English language',
              '2. If you need help with translation, consider using:',
              '   - Translation tools like Google Translate',
              '   - AI assistants like ChatGPT or Claude',
              '',
              'This helps our community provide the best possible support and ensures your issue gets the attention it deserves from our global contributor base.',
              '',
              'Thank you for your understanding! 🙏'
            ].join('\n');

            try {
              // Add comment
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: issueNumber,
                body: commentBody
              });

              console.log('Posted language requirement comment');

              // Add non-english label
              await github.rest.issues.addLabels({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: issueNumber,
                labels: ['non-english']
              });

              console.log('Added non-english label');

              // Close the issue
              await github.rest.issues.update({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: issueNumber,
                state: 'closed',
                state_reason: 'not_planned'
              });

              console.log('Closed the issue');

            } catch (error) {
              core.error('Failed to process non-English issue:', error.message);
              if (error.status === 403) {
                core.error('Permission denied or rate limit exceeded');
              }
            }

name: Restrict task creation

# yamllint disable-line rule:truthy
on:
  issues:
    types: [opened]

permissions: {}

concurrency:
  group: ${{ github.workflow }}-${{ github.event.issue.number }}

jobs:
  add-no-stale:
    name: Add no-stale label
    runs-on: ubuntu-latest
    permissions:
      issues: write # To add labels to issues
    if: >-
      github.event.issue.type.name == 'Task'
      || github.event.issue.type.name == 'Epic'
      || github.event.issue.type.name == 'Opportunity'
    steps:
      - name: Add no-stale label
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            await github.rest.issues.addLabels({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              labels: ['no-stale']
            });

  check-authorization:
    name: Check authorization
    runs-on: ubuntu-latest
    permissions:
      contents: read # To read CODEOWNERS file
      issues: write # To comment on, label, and close issues
    # Only run if this is a Task issue type (from the issue form)
    if: github.event.issue.type.name == 'Task'
    steps:
      - name: Check if user is authorized
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const issueAuthor = context.payload.issue.user.login;

            // First check if user is an organization member
            try {
              await github.rest.orgs.checkMembershipForUser({
                org: 'home-assistant',
                username: issueAuthor
              });
              console.log(`✅ ${issueAuthor} is an organization member`);
              return; // Authorized, no need to check further
            } catch (error) {
              console.log(`ℹ️ ${issueAuthor} is not an organization member, checking codeowners...`);
            }

            // If not an org member, check if they're a codeowner
            try {
              // Fetch CODEOWNERS file from the repository
              const { data: codeownersFile } = await github.rest.repos.getContent({
                owner: context.repo.owner,
                repo: context.repo.repo,
                path: 'CODEOWNERS',
                ref: 'dev'
              });

              // Decode the content (it's base64 encoded)
              const codeownersContent = Buffer.from(codeownersFile.content, 'base64').toString('utf-8');

              // Check if the issue author is mentioned in CODEOWNERS
              // GitHub usernames in CODEOWNERS are prefixed with @
              if (codeownersContent.includes(`@${issueAuthor}`)) {
                console.log(`✅ ${issueAuthor} is a integration code owner`);
                return; // Authorized
              }
            } catch (error) {
              console.error('Error checking CODEOWNERS:', error);
            }

            // If we reach here, user is not authorized
            console.log(`❌ ${issueAuthor} is not authorized to create Task issues`);

            // Close the issue with a comment
            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              body: `Hi @${issueAuthor}, thank you for your contribution!\n\n` +
                    `Task issues are restricted to Open Home Foundation staff, authorized contributors, and integration code owners.\n\n` +
                    `If you would like to:\n` +
                    `- Report a bug: Please use the [bug report form](https://github.com/home-assistant/core/issues/new?template=bug_report.yml)\n` +
                    `- Request a feature: Please submit to [Feature Requests](https://github.com/orgs/home-assistant/discussions)\n\n` +
                    `If you believe you should have access to create Task issues, please contact the maintainers.`
            });

            await github.rest.issues.update({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              state: 'closed'
            });

            // Add a label to indicate this was auto-closed
            await github.rest.issues.addLabels({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              labels: ['auto-closed']
            });

