      - name: Setup Java
        uses: actions/setup-java@de7274f081f381c8f8158605e0321c36c376e2e6  # v6.0.1
        with:
          distribution: 'temurin'
          java-version: ${{ env.JAVA_VERSION }}
      - name: "Cleanup dist files"
        run: rm -fv ./dist/*
      - name: Run Java SDK tests
        working-directory: ./java-sdk
        run: ./gradlew test

  build-java-sdk-docs:
    name: "Java SDK docs"
    needs: [build-info]
    runs-on: ${{ fromJSON(needs.build-info.outputs.runner-type) }}
    timeout-minutes: 30
    permissions:
      contents: read
      packages: read
    if: needs.build-info.outputs.run-java-sdk-tests == 'true'
    env:
      GITHUB_REPOSITORY: ${{ github.repository }}
      GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
      GITHUB_USERNAME: ${{ github.actor }}
      VERBOSE: "true"
    steps:
      - name: "Checkout ${{ github.ref }} ( ${{ github.sha }} )"
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1  # v7.0.1
        with:
          persist-credentials: false
      - name: "Install Breeze"
        uses: ./.github/actions/breeze
      - name: "Build Java SDK Javadoc"
        run: breeze build-docs --sdk-docs-only --sdk=java
      - name: "Upload Javadoc artifact"
        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a  # v7.0.1
        with:
          name: java-sdk-docs
          path: generated/_build/docs/java-sdk/
          retention-days: 7
          if-no-files-found: error
          overwrite: 'true'

  build-ts-sdk-docs:
    name: "TypeScript SDK docs"
    needs: [build-info]
    runs-on: ${{ fromJSON(needs.build-info.outputs.runner-type) }}
    timeout-minutes: 30
    permissions:
      contents: read
      packages: read
    if: needs.build-info.outputs.run-ts-sdk-docs == 'true'
    env:
      GITHUB_REPOSITORY: ${{ github.repository }}
      GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
      GITHUB_USERNAME: ${{ github.actor }}
      VERBOSE: "true"
    steps:
      - name: "Checkout ${{ github.ref }} ( ${{ github.sha }} )"
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1  # v7.0.1
        with:
          persist-credentials: false
      - name: "Install Breeze"
        uses: ./.github/actions/breeze
      - name: "Build TypeScript SDK API reference"
        run: breeze build-docs --sdk-docs-only --sdk=typescript
      - name: "Upload TypeScript SDK docs artifact"
        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a  # v7.0.1
        with:
          name: ts-sdk-docs
          path: generated/_build/docs/ts-sdk/
          retention-days: 7
          if-no-files-found: error
          overwrite: 'true'

  tests-airflow-ctl:
    name: "Airflow CTL tests"
    uses: ./.github/workflows/airflow-distributions-tests.yml
    needs: [build-info]
    permissions:
      contents: read
      packages: read
    with:
      runners: ${{ needs.build-info.outputs.runner-type }}
      platform: ${{ needs.build-info.outputs.platform }}
      default-python-version: "${{ needs.build-info.outputs.default-python-version }}"
      python-versions: ${{ needs.build-info.outputs.python-versions }}
      use-uv: ${{ needs.build-info.outputs.use-uv }}
      canary-run: ${{ needs.build-info.outputs.canary-run }}
      distribution-name: "airflow-ctl"
      distribution-cmd-format: "prepare-airflow-ctl-distributions"
      test-type: "airflow-ctl-tests"
      use-local-venv: 'true'
      test-timeout: 20
    if: needs.build-info.outputs.run-airflow-ctl-tests == 'true'

  finalize-tests:
    name: Finalize tests
    permissions:
      contents: write
      packages: write
    # This will fire when all the jobs from "needs" are either successful or skipped
    if: always() && !failure() && !cancelled()
    needs:
      - additional-ci-image-checks
      - additional-prod-image-tests
      - basic-tests
      - build-info
      - build-prod-images
      - ci-image-checks
      - generate-constraints
      - migration-round-trip
      - mypy-providers
      - providers
      - tests-helm
      - tests-integration-system
      - tests-kubernetes
      - tests-mysql-core
      - tests-mysql-providers
      - tests-non-db-core
      - tests-non-db-providers
      - tests-postgres-core
      - tests-postgres-providers
      - tests-sqlite-core
      - tests-sqlite-providers
      - tests-task-sdk
      - tests-airflow-ctl
      - tests-go-sdk
      - tests-java-sdk
      - build-java-sdk-docs
      - build-ts-sdk-docs
      - tests-with-lowest-direct-resolution-core
      - tests-with-lowest-direct-resolution-providers
    uses: ./.github/workflows/finalize-tests.yml
    with:
      runners: ${{ needs.build-info.outputs.runner-type }}
      platform: ${{ needs.build-info.outputs.platform }}
      python-versions: ${{ needs.build-info.outputs.python-versions }}
      python-versions-list-as-string: ${{ needs.build-info.outputs.python-versions-list-as-string }}
      branch: ${{ needs.build-info.outputs.default-branch }}
      constraints-branch: ${{ needs.build-info.outputs.default-constraints-branch }}
      default-python-version: "${{ needs.build-info.outputs.default-python-version }}"
      upgrade-to-newer-dependencies: ${{ needs.build-info.outputs.upgrade-to-newer-dependencies }}
      include-success-outputs: ${{ needs.build-info.outputs.include-success-outputs }}
      docker-cache: ${{ needs.build-info.outputs.docker-cache }}
      disable-airflow-repo-cache: ${{ needs.build-info.outputs.disable-airflow-repo-cache }}
      canary-run: ${{ needs.build-info.outputs.canary-run }}
      use-uv: ${{ needs.build-info.outputs.use-uv }}
      debug-resources: ${{ needs.build-info.outputs.debug-resources }}

  notify-slack:
    name: "Notify Slack"
    needs:
      - build-info
      - finalize-tests
    if: >-
      always() &&
      !cancelled() &&
      github.event_name == 'schedule' &&
      github.run_attempt == 1
    runs-on: ["ubuntu-slim"]
    steps:
      - name: "Checkout ${{ github.ref }} ( ${{ github.sha }} )"
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1  # v7.0.1
        with:
          persist-credentials: false
      - name: "Get failing jobs"
        id: get-failures
        shell: bash
        run: |
          FAILED_JOBS=$(gh run view "${{ github.run_id }}" \
            --repo "${{ github.repository }}" \
            --json jobs \
            --jq '[.jobs[] | select(.conclusion == "failure") | .name] | sort | .[]')
          echo "failed-jobs<<EOF" >> "${GITHUB_OUTPUT}"
          echo "${FAILED_JOBS}" >> "${GITHUB_OUTPUT}"
          echo "EOF" >> "${GITHUB_OUTPUT}"
          # A literal newline would end the double-quoted YAML scalar the Slack payload
          # interpolates job names into, and the action would reject the whole payload.
          echo "failed-jobs-text=${FAILED_JOBS//$'\n'/\\n}" >> "${GITHUB_OUTPUT}"
          if [[ -n "${FAILED_JOBS}" ]]; then
            echo "has-failures=true" >> "${GITHUB_OUTPUT}"
          else
            echo "has-failures=false" >> "${GITHUB_OUTPUT}"
          fi
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
      - name: "Determine notification action"
        id: notification
        shell: bash
        run: |
          command -v gh >/dev/null 2>&1 || { echo "::error::gh CLI is not installed"; exit 1; }
          gh auth status || gh auth login --with-token <<< "${GITHUB_TOKEN}"
          python3 scripts/ci/slack_notification_state.py
        env:
          ARTIFACT_NAME: "slack-state-tests-${{ github.ref_name }}-amd"
          CURRENT_FAILURES: "${{ steps.get-failures.outputs.failed-jobs }}"
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
      - name: "Upload notification state"
        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a  # v7.0.1
        with:
          name: "slack-state-tests-${{ github.ref_name }}-amd"
          path: ./slack-state/
          retention-days: 7
          overwrite: true
      - name: "Notify Slack (new/changed failures)"
        if: steps.notification.outputs.action == 'notify_new'
        uses: slackapi/slack-github-action@dcb1066f776dd043e64d0e8ba94ca15cc7e1875d  # v4.0.0
        with:
          method: chat.postMessage
          token: ${{ env.SLACK_BOT_TOKEN }}
          # yamllint disable rule:line-length
          payload: |
            channel: "internal-airflow-ci-cd"
            text: "🚨 Failure Alert: Scheduled CI (${{ needs.build-info.outputs.platform }}) on branch *${{ github.ref_name }}*\n\nFailing jobs:\n${{ steps.get-failures.outputs.failed-jobs-text }}\n\n*Details:* <https://github.com/${{ github.repository }}/actions/runs/${{ github.run_id }}|View the failure log>"
            blocks:
              - type: "section"
                text:
                  type: "mrkdwn"
                  text: "🚨 Failure Alert: Scheduled CI (${{ needs.build-info.outputs.platform }}) on *${{ github.ref_name }}*\n\nFailing jobs:\n${{ steps.get-failures.outputs.failed-jobs-text }}\n\n*Details:* <https://github.com/${{ github.repository }}/actions/runs/${{ github.run_id }}|View the failure log>"
          # yamllint enable rule:line-length
      - name: "Notify Slack (still not fixed)"
        if: steps.notification.outputs.action == 'notify_reminder'
        uses: slackapi/slack-github-action@dcb1066f776dd043e64d0e8ba94ca15cc7e1875d  # v4.0.0
        with:
          method: chat.postMessage
          token: ${{ env.SLACK_BOT_TOKEN }}
          # yamllint disable rule:line-length
          payload: |
            channel: "internal-airflow-ci-cd"
            text: "🚨🔁 Still not fixed: Scheduled CI (${{ needs.build-info.outputs.platform }}) on branch *${{ github.ref_name }}*\n\nFailing jobs:\n${{ steps.get-failures.outputs.failed-jobs-text }}\n\n*Details:* <https://github.com/${{ github.repository }}/actions/runs/${{ github.run_id }}|View the failure log>"
            blocks:
              - type: "section"
                text:
                  type: "mrkdwn"
                  text: "🚨🔁 Still not fixed: Scheduled CI (${{ needs.build-info.outputs.platform }}) on *${{ github.ref_name }}*\n\nFailing jobs:\n${{ steps.get-failures.outputs.failed-jobs-text }}\n\n*Details:* <https://github.com/${{ github.repository }}/actions/runs/${{ github.run_id }}|View the failure log>"
          # yamllint enable rule:line-length
      - name: "Notify Slack (all tests passing)"
        if: steps.notification.outputs.action == 'notify_recovery'
        uses: slackapi/slack-github-action@dcb1066f776dd043e64d0e8ba94ca15cc7e1875d  # v4.0.0
        with:
          method: chat.postMessage
          token: ${{ env.SLACK_BOT_TOKEN }}
          # yamllint disable rule:line-length
          payload: |
            channel: "internal-airflow-ci-cd"
            text: "✅ All tests passing: Scheduled CI (${{ needs.build-info.outputs.platform }}) on branch *${{ github.ref_name }}*\n\n*Details:* <https://github.com/${{ github.repository }}/actions/runs/${{ github.run_id }}|View the run log>"
            blocks:
              - type: "section"
                text:
                  type: "mrkdwn"
                  text: "✅ All tests passing: Scheduled CI (${{ needs.build-info.outputs.platform }}) on *${{ github.ref_name }}*\n\n*Details:* <https://github.com/${{ github.repository }}/actions/runs/${{ github.run_id }}|View the run log>"
          # yamllint enable rule:line-length

  summarize-warnings:
    timeout-minutes: 15
    name: "Summarize warnings"
    needs:
      - build-info
      - tests-mysql-core
      - tests-mysql-providers
      - tests-non-db-core
      - tests-non-db-providers
      - tests-postgres-core
      - tests-postgres-providers
      - tests-sqlite-core
      - tests-sqlite-providers
      - tests-task-sdk
      - tests-airflow-ctl
      - tests-special
      - tests-with-lowest-direct-resolution-core
      - tests-with-lowest-direct-resolution-providers
    runs-on: ${{ fromJSON(needs.build-info.outputs.runner-type) }}
    if: needs.build-info.outputs.run-unit-tests == 'true'
    steps:
      - name: "Cleanup repo"
        shell: bash
        run: sudo rm -rf ${GITHUB_WORKSPACE}/*
      - name: "Checkout ${{ github.ref }} ( ${{ github.sha }} )"
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1  # v7.0.1
        with:
          persist-credentials: false
      - name: "Free up disk space"
        shell: bash
        run: ./scripts/tools/free_up_disk_space.sh
      - name: "Download all test warning artifacts from the current build"
        uses: actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c  # v8.0.1
        with:
          path: ./artifacts
          pattern: test-warnings-*
      - name: "Setup python"
        uses: actions/setup-python@5fda3b95a4ea91299a34e894583c3862153e4b97  # v7.0.0
        with:
          python-version: "${{ inputs.default-python-version }}"
      - name: "Summarize all warnings"
        run: |
          ./scripts/ci/testing/summarize_captured_warnings.py ./artifacts \
            --pattern "**/warnings-*.txt" \
            --output ./files
      - name: "Upload artifact for summarized warnings"
        uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a  # v7.0.1
        with:
          name: "test-summarized-warnings"
          path: ./files/warn-summary-*.txt
          retention-days: 7
          if-no-files-found: ignore
          overwrite: true

