      use-uv: ${{ needs.build-info.outputs.use-uv }}
      overlays: ${{ needs.build-info.outputs.kustomize-overlay-names }}
    # Gated by run-kustomize-overlays-tests (computed by SelectiveChecks
    # from changes under chart/kustomize-overlays/ and the narrow set of
    # runner files), NOT by run-helm-tests — a values.yaml tweak should
    # not pull in a 30-40 min kind cluster spin-up for unrelated overlays.
    # AMD-only via the platform guard below: the smoke test is
    # CPU-architecture-neutral (kustomize render + apply + STATUS
