  tests-go-sdk:
    name: "Go SDK tests"
    needs: [build-info]
    runs-on: ${{ fromJSON(needs.build-info.outputs.runner-type) }}
    timeout-minutes: 15
    permissions:
      contents: read
      packages: read
    if: needs.build-info.outputs.run-go-sdk-tests == 'true'
    env:
      GITHUB_REPOSITORY: ${{ github.repository }}
      GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
      GITHUB_USERNAME: ${{ github.actor }}
      VERBOSE: "true"
    steps:
      - name: "Checkout ${{ github.ref }} ( ${{ github.sha }} )"
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1  # v7.0.1
        with:
          persist-credentials: false
      # keep this in sync with go.mod in go-sdk/
      - name: Setup Go
        uses: actions/setup-go@b7ad1dad31e06c5925ef5d2fc7ad053ef454303e  # v7.0.0
        with:
          # Pinned to the patch: actions/go-versions trails Go security releases by weeks, and
          # setup-go resolves from that manifest whenever it can match, so a bare 1.25 lands on a
          # toolchain whose standard library still carries advisories the scan below fails on.
          go-version: '1.25.13'
          cache-dependency-path: go-sdk/go.sum
      # keep this in sync with go.mod in go-sdk/
      - name: Setup Gotestsum
        shell: bash
        run: |
          go install gotest.tools/gotestsum@c4a0df2e75a225d979a444342dd3db752b53619f  # v1.13.0
          gotestsum --version
      - name: "Cleanup dist files"
        run: rm -fv ./dist/*
      - name: Run Go tests
        working-directory: ./go-sdk
        run: gotestsum --format github-actions ./...
      # Go modules have no central registry that pre-scans releases, so we scan our own
      # dependency graph against the Go vulnerability database. govulncheck is reachability
      # based, so it only fails on advisories that actually affect code we call. The version
      # tag is immutable (Go modules are content-addressed via the checksum database).
      - name: Scan Go dependencies for known vulnerabilities
        working-directory: ./go-sdk
        run: |
          go install golang.org/x/vuln/cmd/govulncheck@v1.6.0
          govulncheck ./...

