# Generic auto-approve for machine-created PRs.
# Add new rules to the whitelist in the check step; approval runs when any rule matches.
# Each rule can optionally specify a `token` field to control the approving identity:
#   'kibana' - approve as kibanamachine using KIBANAMACHINE_TOKEN
#   'github' - approve as github-actions[bot] using the default GITHUB_TOKEN
name: Auto-approve machine PRs

on:
  pull_request_target:
    types:
      - opened

jobs:
  approve:
    name: Auto-approve machine PR
    runs-on: ubuntu-latest
    permissions:
      pull-requests: write
    steps:
      - id: check
        name: Check if PR should be auto-approved
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            const user = context.payload.pull_request.user.login;
            const headRef = context.payload.pull_request.head.ref;
            const baseRef = context.payload.pull_request.base.ref;

            const whitelist = [
              // { user: 'kibanamachine', branchPrefix: 'api_docs', baseMatch: /^main$/, token: 'kibana' },
              // { user: 'kibanamachine', branchPrefix: 'backport', baseNotMatch: /^main$/, token: 'kibana' },
              { user: 'kibanamachine', branchPrefix: 'scout_metadata_update', token: 'github' },
              { user: 'kibanamachine', branchPrefix: 'update-pipeline-resource-defs', baseMatch: /^main$/, token: 'github' },
              { user: 'kibanamachine', branchPrefix: 'bump-versions', token: 'github' },
              { user: 'elastic-vault-github-plugin-prod[bot]', branchPrefix: 'update-bundled-packages', paths: ['fleet_packages.json'], token: 'kibana' },
            ];

            // Fetch the list of changed files in the PR
            const files = await github.rest.pulls.listFiles({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.payload.pull_request.number,
            });

            const changedFiles = files.data.map(file => file.filename);
            core.info(`Changed files: ${changedFiles.join(', ')}`);

            const matchedRule = whitelist.find((rule) => {
              if (rule.user !== user) return false;
              if (!headRef.startsWith(rule.branchPrefix)) return false;
              if (rule.baseMatch && !rule.baseMatch.test(baseRef)) return false;
              if (rule.baseNotMatch && rule.baseNotMatch.test(baseRef)) return false;

              // If paths is specified, verify at least one changed file matches
              if (rule.paths) {
                const hasMatchingFile = changedFiles.some(file =>
                  rule.paths.some(path => {
                    // Support glob patterns
                    if (path.includes('*')) {
                      const regex = new RegExp('^' + path.replace(/\*/g, '.*') + '$');
                      return regex.test(file);
                    }
                    return file === path;
                  })
                );
                if (!hasMatchingFile) {
                  core.info(`File check failed for rule ${rule.user}/${rule.branchPrefix}: no changed files match paths`);
                  return false;
                }
              }

              return true;
            });

            core.setOutput('should_approve', matchedRule ? 'true' : 'false');
            core.setOutput('token', matchedRule?.token ?? 'kibana');

      - uses: hmarr/auto-approve-action@f0939ea97e9205ef24d872e76833fa908a770363 # v4.0.0
        name: Approve as github-actions[bot]
        if: steps.check.outputs.should_approve == 'true' && steps.check.outputs.token == 'github'
        with:
          github-token: ${{ github.token }}

      - uses: hmarr/auto-approve-action@f0939ea97e9205ef24d872e76833fa908a770363 # v4.0.0
        name: Approve as kibanamachine
        if: steps.check.outputs.should_approve == 'true' && steps.check.outputs.token == 'kibana'
        with:
          github-token: ${{ secrets.KIBANAMACHINE_TOKEN }}

name: Check reviewable commit

on:
  workflow_call:
    outputs:
      should_review:
        description: Whether the triggering commit should start a review.
        value: ${{ jobs.check_reviewable_commit.outputs.should_review }}

jobs:
  check_reviewable_commit:
    runs-on: ubuntu-slim
    permissions:
      contents: read
    outputs:
      should_review: ${{ steps.check_commit.outputs.should_review }}
    steps:
      - name: Skip merge commits
        id: check_commit
        uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        with:
          script: |
            if (context.payload.action !== 'synchronize') {
              core.setOutput('should_review', 'true');
              return;
            }

            const head = context.payload.pull_request.head;
            const { data: commit } = await github.rest.repos.getCommit({
              owner: head.repo.owner.login,
              repo: head.repo.name,
              ref: head.sha,
            });
            const shouldReview = commit.parents.length <= 1;
            core.info(shouldReview ? 'Reviewing code push.' : 'Skipping merge commit.');
            core.setOutput('should_review', String(shouldReview));

name: Close stale failed-test issues

# Daily sweep that closes `failed-test` issues created by kibanamachine when
# they have had no activity for 21 days. Any activity that updates the issue
# (a new failure comment, a human comment, an edit) restarts the countdown.
#
# Closing is safe: the failed test reporter reopens the issue automatically
# if the test fails again. Issues labeled `skipped-test` are excluded because
# they stay open on purpose as a reminder to unskip the test.

on:
  schedule:
    - cron: '0 6 * * *'
  workflow_dispatch:
    inputs:
      dry_run:
        description: 'Log what would be closed instead of closing'
        type: boolean
        default: false

permissions:
  issues: write
  contents: read

jobs:
  sweep:
    name: Close failed-test issues with no activity for 21 days
    runs-on: ubuntu-slim
    if: github.repository == 'elastic/kibana'
    concurrency:
      group: close-stale-failed-test-issues
      cancel-in-progress: true
    steps:
      - uses: actions/github-script@3a2844b7e9c422d3c10d287c895573f7108da1b3 # v9.0.0
        env:
          DRY_RUN: ${{ inputs.dry_run == true }}
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const LABEL = 'failed-test';
            const EXCLUDED_LABELS = ['skipped-test'];
            const CREATOR = 'kibanamachine';
            const DAYS_UNTIL_CLOSE = 21;
            // Drain the backlog gradually to avoid rate limits and a
            // notification storm on the first runs
            const MAX_CLOSES_PER_RUN = 200;
            const dryRun = process.env.DRY_RUN === 'true';
            const cutoff = Date.now() - DAYS_UNTIL_CLOSE * 24 * 60 * 60 * 1000;

            const getLabels = (item) =>
              item.labels.map((label) => (typeof label === 'string' ? label : label.name));

            const items = await github.paginate(github.rest.issues.listForRepo, {
              owner: context.repo.owner,
              repo: context.repo.repo,
              state: 'open',
              labels: LABEL,
              creator: CREATOR,
              per_page: 100,
            });

            let closed = 0;
            for (const item of items) {
              if (closed >= MAX_CLOSES_PER_RUN) {
                core.info(`Reached the limit of ${MAX_CLOSES_PER_RUN} closes, stopping`);
                break;
              }
              if (
                item.pull_request ||
                new Date(item.updated_at).getTime() > cutoff ||
                getLabels(item).some((label) => EXCLUDED_LABELS.includes(label))
              ) {
                continue;
              }

              if (dryRun) {
                closed += 1;
                core.info(`[dry run] would close #${item.number} (updated ${item.updated_at}): ${item.title}`);
                continue;
              }

              // Re-check right before closing to narrow the race with new
              // failures and manual label changes
              const { data: fresh } = await github.rest.issues.get({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: item.number,
              });
              const freshLabels = getLabels(fresh);
              if (
                fresh.state !== 'open' ||
                !freshLabels.includes(LABEL) ||
                freshLabels.some((label) => EXCLUDED_LABELS.includes(label)) ||
                new Date(fresh.updated_at).getTime() > cutoff
              ) {
                continue;
              }

              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: item.number,
                body: [
                  `Closing as this test hasn't failed in 3 weeks, which likely means the flakiness has resolved itself. This issue will reopen automatically if the test fails again.`,
                  '',
                  '<!-- failed-test-stale-closed -->',
                ].join('\n'),
              });
              await github.rest.issues.update({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: item.number,
                state: 'closed',
                state_reason: 'not_planned',
              });
              closed += 1;
              core.info(`Closed #${item.number} (updated ${item.updated_at}): ${item.title}`);
            }
            core.info(
              `Checked ${items.length} open "${LABEL}" issue(s) created by ${CREATOR}, closed ${closed}${dryRun ? ' (dry run)' : ''}`
            );
